<script setup lang="ts">
const props=defineProps<{warehouseId?:number;goodsIds:number[]}>()
const open=defineModel<boolean>('open',{default:false})
const emit=defineEmits<{saved:[]}>()
const {t}=useI18n(),{bizErrorMessage}=useBizError()
const mode=ref('fixed'),low=ref<any>(null),high=ref<any>(null),windowDays=ref<any>(30),coverDays=ref<any>(14),overstockDays=ref<any>(90),minimum=ref<any>(1)
const rows=ref<any[]>([]),selected=ref<(string|number)[]>([]),loading=ref(false),busy=ref(false),error=ref(''),stale=ref(false)
let generation=0
const preview=async()=>{
 if(!props.warehouseId)return
 const seq=++generation;loading.value=true;error.value='';rows.value=[];selected.value=[]
 const result=await httpRequest<any>('/api/warehouse/inventory/thresholds/suggest',{headers:warehouseHeaders(props.warehouseId),params:{goods_ids:props.goodsIds.join(','),per_page:100,window_days:windowDays.value,cover_days:coverDays.value,overstock_days:overstockDays.value,min_quantity:minimum.value},onError:err=>{if(seq===generation)error.value=bizErrorMessage(err)}})
 if(seq!==generation)return
 if(result){rows.value=result.items.map((row:any)=>({...row,id:row.goods.id,low:mode.value==='fixed'?(low.value==null||low.value===''?row.current_low:Number(low.value)):row.suggested_low,high:mode.value==='fixed'?(high.value==null||high.value===''?row.current_high:Number(high.value)):row.suggested_high}));selected.value=rows.value.filter(row=>row.low!==null&&row.high!==null).map(row=>row.id);stale.value=false}
 loading.value=false
}
watch(open,value=>{if(value){preview()}else{generation++;rows.value=[]}})
watch([mode,low,high,windowDays,coverDays,overstockDays,minimum],()=>{stale.value=true})
const save=async()=>{
 if(busy.value||stale.value||!selected.value.length)return
 const items=rows.value.filter(row=>selected.value.includes(row.id)).map(row=>({goods_id:row.id,low_stock_threshold:Number(row.low),high_stock_threshold:Number(row.high)}))
 busy.value=true;error.value=''
 try{
  const dry=await httpRequest<any>('/api/warehouse/inventory/thresholds',{method:'PUT',headers:warehouseHeaders(props.warehouseId),body:{items,dry_run:true},onError:err=>{error.value=bizErrorMessage(err)}})
  if(!dry)return
  const result=await httpRequest<any>('/api/warehouse/inventory/thresholds',{method:'PUT',headers:warehouseHeaders(props.warehouseId),body:{items},onError:err=>{error.value=bizErrorMessage(err)}})
  if(result){showToast(t('action-results.success'),'success');open.value=false;emit('saved')}
 }finally{busy.value=false}
}
const columns=computed(()=>[{key:'goods',label:t('nav.goods')},{key:'avg_daily_out',label:t('threshold.daily'),type:'qty' as const,keepZero:true},{key:'available_stock_for_sale',label:t('goods.ui.available'),type:'qty' as const,strong:true,keepZero:true},{key:'current',label:t('threshold.current')},{key:'low',label:t('inventory.ui.low')},{key:'high',label:t('inventory.ui.high')}])
</script>
<template><WModal v-model:open="open" :title="t('inventory.ui.thresholds')" size="xl" :closable="!busy"><div class="w-threshold-editor"><p>{{t('threshold.scope',{count:goodsIds.length})}}</p><div class="w-threshold-modes"><section :class="{'is-selected':mode==='fixed'}"><label><input v-model="mode" type="radio" value="fixed" :disabled="busy" /><strong>{{t('threshold.fixed')}}</strong></label><WFormGrid><WField :label="t('inventory.ui.low')" :span="6"><WInput v-model="low" type="number" min="-1" step="1" :disabled="busy||mode!=='fixed'" /></WField><WField :label="t('inventory.ui.high')" :span="6"><WInput v-model="high" type="number" min="-1" step="1" :disabled="busy||mode!=='fixed'" /></WField></WFormGrid><small>{{t('threshold.keep')}} {{t('inventory.ui.disabled')}}</small></section><section :class="{'is-selected':mode==='suggest'}"><label><input v-model="mode" type="radio" value="suggest" :disabled="busy" /><strong>{{t('threshold.suggest')}}</strong></label><WFormGrid><WField :label="t('threshold.window')" :span="6"><WInput v-model="windowDays" type="number" min="1" :disabled="busy||mode!=='suggest'" /></WField><WField :label="t('threshold.cover')" :span="6"><WInput v-model="coverDays" type="number" min="1" :disabled="busy||mode!=='suggest'" /></WField><WField :label="t('threshold.overstock')" :span="6"><WInput v-model="overstockDays" type="number" min="1" :disabled="busy||mode!=='suggest'" /></WField><WField :label="t('threshold.minimum')" :span="6"><WInput v-model="minimum" type="number" min="0" :disabled="busy||mode!=='suggest'" /></WField></WFormGrid></section></div><div class="w-threshold-preview"><h3>{{t('threshold.preview')}}</h3><WButton size="sm" :loading="loading" :disabled="busy" @click="preview">{{t('threshold.refresh')}}</WButton></div><WAlert v-if="error" tone="block" :title="error" /><WAlert v-if="stale" tone="warn" :title="t('threshold.stale')" /><WTable v-model:selected="selected" selectable :row-selectable="row=>row.low!==null&&row.high!==null" :columns="columns" :rows="rows" :loading="loading" inset><template #cell-goods="{row}">{{row.goods.name}}<span class="w-threshold-sub">{{row.goods.code}}</span></template><template #cell-current="{row}">{{row.current_low<0?'—':row.current_low}} / {{row.current_high<0?'—':row.current_high}}</template><template #cell-low="{row}"><WInput v-if="row.low!==null" v-model="row.low" type="number" min="-1" step="1" :aria-label="t('inventory.ui.low')+' '+row.goods.code" :disabled="busy" /><span v-else>{{t('threshold.no-outbound')}}</span></template><template #cell-high="{row}"><WInput v-if="row.high!==null" v-model="row.high" type="number" min="-1" step="1" :aria-label="t('inventory.ui.high')+' '+row.goods.code" :disabled="busy" /></template></WTable></div><template #footer><span>{{t('inventory.ui.selected',{count:selected.length})}}</span><WButton :disabled="busy" @click="open=false">{{t('button.cancel')}}</WButton><WButton variant="primary" :loading="busy" :disabled="stale||loading||!selected.length" @click="save">{{t('button.save')}}</WButton></template></WModal></template>
<style scoped>
.w-threshold-editor{display:flex;flex-direction:column;gap:16px}.w-threshold-editor p{margin:0;font-size:13px;color:var(--w-text-2)}.w-threshold-modes{display:grid;grid-template-columns:1fr 1fr;gap:12px}.w-threshold-modes section{display:flex;flex-direction:column;gap:12px;padding:12px;border:1px solid var(--w-border);border-radius:6px}.w-threshold-modes section.is-selected{border-color:var(--w-pri);background:var(--w-sel-bg)}.w-threshold-modes label{display:flex;align-items:center;gap:8px}.w-threshold-modes input[type=radio]{accent-color:var(--w-pri);width:16px;height:16px}.w-threshold-modes strong{font-size:14px;font-weight:600}.w-threshold-modes small{font-size:12px;color:var(--w-text-3)}.w-threshold-preview{display:flex;align-items:center;justify-content:space-between}.w-threshold-preview h3{margin:0;font-size:14px;line-height:22px;font-weight:600}.w-threshold-sub{display:block;font-size:12px;line-height:18px;color:var(--w-text-3)}.w-threshold-editor :deep(.w-table){min-width:800px}.w-threshold-editor :deep(td .w-input){min-width:90px;max-width:120px}@media(max-width:650px){.w-threshold-modes{grid-template-columns:1fr}}
</style>
